import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export default function Page() {
  const dataPromise = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsSection dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<RevenueChartFallback />}>
        <RevenueChartSection dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<LatestInvoicesFallback />}>
        <LatestInvoicesSection dataPromise={dataPromise} />
      </Suspense>
    </main>
  )
}

async function CardStatsSection({
  dataPromise,
}: {
  dataPromise: Promise<DashboardData>
}) {
  const data = await dataPromise
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection({
  dataPromise,
}: {
  dataPromise: Promise<DashboardData>
}) {
  const data = await dataPromise
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesSection({
  dataPromise,
}: {
  dataPromise: Promise<DashboardData>
}) {
  const data = await dataPromise
  return <LatestInvoices invoices={data.invoices} />
}

function CardStatsFallback() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-hidden="true">
      <div className="card skeleton" />
      <div className="card skeleton" />
    </div>
  )
}

function RevenueChartFallback() {
  return (
    <div className="chart skeleton" aria-hidden="true">
      <h2>Revenue</h2>
    </div>
  )
}

function LatestInvoicesFallback() {
  return (
    <div className="invoices skeleton" aria-hidden="true">
      <h2>Latest Invoices</h2>
    </div>
  )
}

